ame="title" maxlength="180" value="<?= e($resource['title']) ?>" required></label><label class="field"><span>Category</span><input name="category" maxlength="100" value="<?= e($resource['category']) ?>" required></label><label class="field"><span>Summary</span><textarea name="summary" rows="2" maxlength="500" required><?= e($resource['summary']) ?></textarea></label><label class="field"><span>Content</span><textarea name="content" rows="8" maxlength="30000" required><?= e($resource['content']) ?></textarea></label><button class="button button-outline">Update resource</button></form></details><form method="post" action="<?= e(pageUrl('admin')) ?>"><?= formToken() ?><input type="hidden" name="action" value="toggle_resource"><input type="hidden" name="resource_id" value="<?= e($resource['id']) ?>"><button class="button button-text"><?= $resource['is_published'] ? 'Unpublish' : 'Publish' ?></button></form></div><?php endforeach; ?></div><?php endif; ?></section></div><?php endif; ?>
